import{_ as e,o as a,c as o,a5 as t}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"WordPress 手机端跳转插件 — Mobile Redirect","description":"","frontmatter":{"标题":"WordPress 手机端跳转插件 — Mobile Redirect","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["301重定向","UA匹配","User-Agent","WordPress","微信浏览器","手机跳转","浏览器识别","移动端","设备跳转"]},"headers":[],"relativePath":"md/wordpress主题插件/WordPress 手机端跳转插件 — Mobile Redirect.md","filePath":"md/wordpress主题插件/WordPress 手机端跳转插件 — Mobile Redirect.md"}'),i={name:"md/wordpress主题插件/WordPress 手机端跳转插件 — Mobile Redirect.md"};function n(s,r,l,b,d,h){return a(),o("div",null,[...r[0]||(r[0]=[t('<h1 id="wordpress-手机端跳转插件-—-mobile-redirect" tabindex="-1">WordPress 手机端跳转插件 — Mobile Redirect <a class="header-anchor" href="#wordpress-手机端跳转插件-—-mobile-redirect" aria-label="Permalink to &quot;WordPress 手机端跳转插件 — Mobile Redirect&quot;">​</a></h1><blockquote><p>基于 User-Agent 规则将手机、平板或指定 App 浏览器访问自动 301 重定向到指定地址。内置 20+ 条预置规则，支持自定义 UA 关键词匹配，管理后台、AJAX、REST API、登录、Cron 等请求自动跳过。</p></blockquote><p><strong>版本</strong>：v1.5.1<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/88791748-3872-400e-ad83-2dd63b9131f1.png" alt=""></p><p>本插件根据访客浏览器的 User-Agent 字符串自动识别其设备类型和浏览器来源，当匹配到已启用的规则时，将访客 301 永久重定向到预设的目标地址。</p><p>插件在后台提供了规则配置管理界面，支持每条规则独立开关、自定义 UA 关键词（支持管道符分隔和简单正则）、一键模块总开关控制。同时内置中英双语界面，语言切换即时生效无需保存。</p><p>重定向逻辑运行于 WordPress 的 template_redirect 钩子（优先级 1），自动排除管理后台、AJAX 请求、REST API、登录页、Cron 任务和 XML-RPC 请求，确保网站管理功能不受影响。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="_20-条预置浏览器规则" tabindex="-1">20+ 条预置浏览器规则 <a class="header-anchor" href="#_20-条预置浏览器规则" aria-label="Permalink to &quot;20+ 条预置浏览器规则&quot;">​</a></h3><p>插件内置了覆盖国内主流 App 和手机/平板浏览器的 21 条预置规则，每条规则均配有预设的 UA 关键词和独立的启用开关：</p><p>— 微信内置浏览器：匹配 MicroMessenger 标识<br> — QQ 内置浏览器 / QQ 浏览器（腾讯）：匹配 QQ/、MQQBrowser、QQBrowser 标识<br> — 腾讯客户端 / QQ 空间客户端：匹配 TencentTraveler、Qzone/ 等腾讯系 UA 标识<br> — UC 浏览器：匹配 UCBrowser、UCWEB、UC Browser 标识<br> — 百度浏览器：匹配 baidubrowser、baiduboxapp 等标识<br> — 搜狗浏览器：匹配 Sogou、MetaSr、SogouMobileBrowser 标识<br> — 手机浏览器 / 平板设备：匹配 iPhone、Android、iPad、Tablet 等通用移动设备标识<br> — Opera Mini/Mobile、Firefox 移动版、Edge 移动版<br> — 360 浏览器、猎豹浏览器、夸克浏览器<br> — 小米浏览器（Miui）、华为浏览器、Vivo 浏览器、OPPO 浏览器、三星浏览器</p><h3 id="自定义-ua-关键词" tabindex="-1">自定义 UA 关键词 <a class="header-anchor" href="#自定义-ua-关键词" aria-label="Permalink to &quot;自定义 UA 关键词&quot;">​</a></h3><p>每条规则的 UA 关键词均可在后台自由编辑，支持以下灵活配置：</p><p>— 管道符（|）分隔多个关键词，命中任意一个即触发跳转<br> — 支持简单正则表达式（如 Firefox.*Mobile 匹配 Firefox 移动版的多种变体）<br> — 当正则语法无效时自动回退为大小写不敏感的纯文本子串匹配，确保规则鲁棒性</p><h3 id="模块总开关" tabindex="-1">模块总开关 <a class="header-anchor" href="#模块总开关" aria-label="Permalink to &quot;模块总开关&quot;">​</a></h3><p>— 后台设置页提供模块总开关（Toggle Switch），一键启用或禁用全部跳转规则<br> — 关闭总开关后配置表单自动折叠隐藏，界面简洁清晰<br> — 总开关状态实时保存，无需额外操作</p><h3 id="自动排除管理请求" tabindex="-1">自动排除管理请求 <a class="header-anchor" href="#自动排除管理请求" aria-label="Permalink to &quot;自动排除管理请求&quot;">​</a></h3><p>插件在以下场景自动跳过重定向逻辑，无需手动配置：</p><p>— WordPress 管理后台（is_admin）<br> — AJAX 请求（wp_doing_ajax）<br> — REST API 请求（REST_REQUEST 常量）<br> — 登录页（wp-login.php）<br> — Cron 任务（wp-cron.php）<br> — XML-RPC 请求（xmlrpc.php）</p><h3 id="_301-永久重定向" tabindex="-1">301 永久重定向 <a class="header-anchor" href="#_301-永久重定向" aria-label="Permalink to &quot;301 永久重定向&quot;">​</a></h3><p>匹配到规则后使用 wp_safe_redirect 执行 301 永久重定向，对搜索引擎友好，有利于 SEO 权重传递。</p><h3 id="传统-antibot-配置迁移" tabindex="-1">传统 AntiBot 配置迁移 <a class="header-anchor" href="#传统-antibot-配置迁移" aria-label="Permalink to &quot;传统 AntiBot 配置迁移&quot;">​</a></h3><p>插件激活时自动检测旧版 AntiBot 插件的配置数据（支持 WordPress 选项表和 config.json 文件两种存储格式），如果存在原有的手机设备跳转规则，自动导入到本插件中，实现无缝升级。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>— 后台界面支持中文（zh_CN）和英文（en_US）两种语言，也可选择「自动」跟随 WordPress 站点语言<br> — 语言切换通过独立的 admin-post 表单即时生效，无需保存设置<br> — 翻译通过 PHP 数组 + gettext 过滤器实现，不依赖 .po/.mo 文件</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 mobile_tiaozhuan 文件夹上传至网站 wp-content/plugins/ 目录，进入 WordPress 后台「插件」页面，找到「Mobile Redirect」并点击启用。</p><h3 id="第二步-配置跳转规则" tabindex="-1">第二步：配置跳转规则 <a class="header-anchor" href="#第二步-配置跳转规则" aria-label="Permalink to &quot;第二步：配置跳转规则&quot;">​</a></h3><p>启用后，后台左侧菜单会出现「Mobile Redirect」入口，点击进入配置页面：</p><p>— 页面顶部提供界面语言切换下拉框，选择后即时生效<br> — 「手机端跳转规则」模块卡片右上角为模块总开关，关闭后所有规则停止生效<br> — 在规则表格中，勾选需要启用的规则对应的「启用」复选框<br> — 在「跳转地址」列填入目标 URL（如 <a href="https://m.example.com/%EF%BC%89" target="_blank" rel="noreferrer">https://m.example.com/）</a><br> — 如需修改 UA 关键词，直接在「UA 关键词」文本框中编辑，多个关键词用 | 分隔<br> — 点击页面底部「保存设置」按钮</p><h3 id="第三步-验证效果" tabindex="-1">第三步：验证效果 <a class="header-anchor" href="#第三步-验证效果" aria-label="Permalink to &quot;第三步：验证效果&quot;">​</a></h3><p>— 使用对应的浏览器或修改 User-Agent 模拟手机/平板设备访问网站前台<br> — 确认匹配到规则时自动跳转到预设的目标地址<br> — 访问 WordPress 后台确认不受影响</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 跳转规则按表格顺序从上到下逐条匹配，命中第一条后立即跳转，后续规则不再检查。如有多条规则可能同时匹配同一浏览器，请通过调整规则顺序控制优先级<br> — UA 关键词为空或跳转地址为空的规则不会被触发，即使已勾选启用<br> — 插件使用 301 永久重定向，浏览器可能会缓存重定向结果，测试期间建议使用隐私/无痕模式<br> — 与缓存插件共用时，建议将重定向逻辑排除在页面缓存之外，插件在 template_redirect 钩子优先级 1 执行，通常早于大多数缓存插件<br> — 「严格」列目前为预留字段，暂不影响跳转行为</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-5-1-2026" tabindex="-1">v1.5.1（2026） <a class="header-anchor" href="#v1-5-1-2026" aria-label="Permalink to &quot;v1.5.1（2026）&quot;">​</a></h3><p>— 新增中英双语界面支持，语言切换即时生效无需保存<br> — 新增模块总开关（Toggle Switch），一键启用或禁用全部跳转规则<br> — 新增模块卡片 UI，关闭总开关后配置表单自动折叠<br> — 优化管理界面 CSS 样式，适配 WordPress 后台整体风格<br> — 更新 textdomain 和标识符与插件 slug 对齐</p><h3 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h3><p>— 初始版本发布<br> — 内置 21 条预置手机/App 浏览器规则<br> — 自定义 UA 关键词匹配，支持管道符分隔和简单正则<br> — Settings API 配置注册与数据持久化<br> — 传统 AntiBot 插件配置自动迁移<br> — 自动排除管理后台、AJAX、REST API、登录、Cron、XML-RPC 请求</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3025.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3025.html</a></p>',45)])])}const g=e(i,[["render",n]]);export{c as __pageData,g as default};
